def cargar_catalogo_base(apps, schema_editor):
    GymMachine = apps.get_model('plans', 'GymMachine')
    CatalogoEjercicio = apps.get_model('plans', 'CatalogoEjercicio')
    maquinas = {}
    for nombre, categoria in MAQUINAS:
        maquina, _ = GymMachine.objects.get_or_create(name=nombre, defaults={'category': categoria, 'notes': 'Equipo base de catálogo.', 'is_active': True})
        maquinas[nombre] = maquina
    for identificador, nombre, grupo, maquina_nombre, categoria, instrucciones in EJERCICIOS:
        CatalogoEjercicio.objects.update_or_create(
            identificador_origen=f'gymhub-base:{identificador}',
            defaults={'nombre': nombre, 'categoria': 'fuerza', 'parte_cuerpo': categoria, 'equipo': maquina_nombre or 'peso corporal', 'musculo_objetivo': categoria, 'grupo_muscular': categoria, 'grupo_muscular_plan': grupo, 'musculos_secundarios': [], 'instrucciones_es': instrucciones, 'pasos_es': [], 'imagen_url': '', 'animacion_url': '', 'atribucion_media': 'Catálogo base GymHub', 'version_origen': 'GymHub/base-1', 'esta_activo': True, 'maquina_recomendada': maquinas.get(maquina_nombre)},
        )

